from collections import Counter
from itertools import combinations

def components(grid, bg):
    h, w = len(grid), len(grid[0])
    seen, out = set(), []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack, cells = [(r, c)], []
            seen.add((r, c))
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx))
                        stack.append((yy,xx))
            out.append((color, cells))
    return out

def norm(cells):
    y0 = min(y for y, x in cells); x0 = min(x for y, x in cells)
    return frozenset((y-y0, x-x0) for y, x in cells)

def corner_l(cells):
    pts = set(cells)
    y0, y1 = min(y for y,x in pts), max(y for y,x in pts)
    x0, x1 = min(x for y,x in pts), max(x for y,x in pts)
    for y in (y0,y1):
        for x in (x0,x1):
            expected = {(y,xx) for xx in range(x0,x1+1)} | {(yy,x) for yy in range(y0,y1+1)}
            if pts == expected:
                return True
    return False

def transform(grid):
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    objs = components(grid, bg)
    markers = [o for o in objs if corner_l(o[1])]
    if not markers:
        return [row[:] for row in grid]
    marker = max(markers, key=lambda o: len(o[1]))
    groups = {}
    for obj in objs:
        groups.setdefault(norm(obj[1]), []).append(obj)
    candidates = []
    for sh, group in groups.items():
        if len(group) < 2:
            continue
        # Widest-separated repeated motifs identify the pattern pair to alter.
        sep = max(min(abs(y1-y2)+abs(x1-x2) for y1,x1 in a[1] for y2,x2 in b[1])
                  for a,b in combinations(group, 2))
        candidates.append((sep, len(sh), group))
    if not candidates:
        return [row[:] for row in grid]
    _, _, group = max(candidates, key=lambda item: (item[0], item[1]))
    # Keep the earlier copy and recolor the later copy to the marker's color.
    target = max(group, key=lambda o: (min(y for y,x in o[1]), min(x for y,x in o[1])))
    out = [row[:] for row in grid]
    for y, x in target[1]:
        out[y][x] = marker[0]
    return out

